const schema = $('MSSQL Get Schema').all().map(i => i.json);
const telemetry = $('Postgres Get Telemetry').first()?.json || {};
const security = $('Postgres Get Security').first()?.json || {};

const contextStr = `
MSSQL Customer Database Tables:
${JSON.stringify(schema.slice(0, 100), null, 2)}

Live PC Server Telemetry:
- Host: ${telemetry.server_name || 'Local PC'}
- Status: ${telemetry.status || 'OPERATIONAL'}
- CPU Load: ${telemetry.cpu_usage || 0}%
- Memory Load: ${telemetry.memory_usage || 0}%
- Disk Load: ${telemetry.disk_usage || 0}%
- Uptime: ${telemetry.uptime || 'unknown'}

Security Status snapshot:
- Threat Level: ${security.threat_level || 'LOW'}
- Risk Score: ${security.risk_score || 0}
- Failed Logins: ${security.failed_logins || 0}
- Successful Logins: ${security.successful_logins || 0}
- Blocked IPs: ${security.blocked_ips || 0}
`;

return [{
  json: {
    context: contextStr,
    question: $('Webhook').first().json.body.message || 'Help me analyze this systems status.',
    session_id: $('Webhook').first().json.body.session_id || 'session_default'
  }
}];

const aiOutput = $('DBA RAG Agent').first().json.output || $('DBA RAG Agent').first().json.text || '';
const promptData = $('Format RAG Context').first().json;

return [{
  json: {
    session_id: promptData.session_id,
    answer: aiOutput,
    question: promptData.question,
    confidence: 90,
    mode: 'ai'
  }
}];

